const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountStanley = ee.Geometry.Point([29.872, 0.385]).buffer(10000); // 10km buffer
  const start2020 = '2020-01-01';
  const end2020 = '2020-03-31';
  const start2024 = '2024-01-01';
  const end2024 = '2024-03-31';

  // 2. Data Acquisition - Sentinel-2 for NDSI (snow/ice detection)
  const getSnowCover = (startDate, endDate) => {
    const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(mountStanley)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    // Cloud masking using QA60
    const maskClouds = (img) => {
      const qa = img.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return img.updateMask(mask);
    };

    const processed = col.map(maskClouds)
      .map(img => {
        const ndsi = img.normalizedDifference(['B3', 'B11']).rename('NDSI');
        return img.addBands(ndsi);
      })
      .select('NDSI');

    return processed;
  };

  const snow2020 = getSnowCover(start2020, end2020);
  const snow2024 = getSnowCover(start2024, end2024);

  // Check collection sizes
  const size2020 = snow2020.size().getInfo();
  const size2024 = snow2024.size().getInfo();
  console.log(`2020 Images: ${size2020}, 2024 Images: ${size2024}`);

  if (size2020 === 0 || size2024 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Create median composites and threshold (NDSI > 0.4 for snow)
  const composite2020 = snow2020.median();
  const composite2024 = snow2024.median();

  const snowMask2020 = composite2020.gt(0.4).selfMask();
  const snowMask2024 = composite2024.gt(0.4).selfMask();

  // Count valid snow pixels
  const countValid = (img) => {
    return img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: mountStanley,
      scale: 1000,
      maxPixels: 1e9,
    }).get('NDSI').getInfo();
  };

  const count2020 = countValid(snowMask2020);
  const count2024 = countValid(snowMask2024);
  console.log(`2020 Snow Pixels: ${count2020}, 2024 Snow Pixels: ${count2024}`);

  if (count2020 === 0 || count2024 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation & Validation
  if (count2020 === null || count2024 === null || 
      count2020 === undefined || count2024 === undefined ||
      !isFinite(count2020) || !isFinite(count2024)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Final Answer (decrease if 2024 < 2020)
  if (count2024 < count2020) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
